int main(int argc,char**argv)try{if(argc!=2)return 2;std::filesystem::path out=argv[1];std::filesystem::create_directories(out);Scene scene;append_humanoid(scene,humanoid_baseline_defaults("vroid-beta-male"),"Real CC0 authoring",{},64);auto selected=std::find_if(scene.objects().begin(),scene.objects().end(),[](const auto&o){return bool(o.appearance);});if(selected==scene.objects().end())return 3;const auto id=selected->id;auto &part=scene.object(id);part.painted=part.painted->snapshot();Brush b;b.from=b.to=part.painted->mesh().positions.front();b.normal={0,0,1};b.radius=5;b.strength=.7f;PaintSettings p;p.channel=PaintChannel::Color;p.color={.9f,.2f,.1f,1};p.front_only=false;part.painted->begin_stroke();part.painted->stamp(b,p);if(!part.painted->end_stroke())return 4;const auto original=scene.encode();NativeAuthoringExport owner;owner.scene=std::make_shared<const Scene>(scene.snapshot());owner.allow_portable_fallback=true;auto report=export_glb_authoring(owner,out/"real-authoring.glb");auto data=bytes(out/"real-authoring.glb");const size_t count=uint32_t(data.at(12))|uint32_t(data.at(13))<<8|uint32_t(data.at(14))<<16|uint32_t(data.at(15))<<24;const auto j=nlohmann::json::parse(data.begin()+20,data.begin()+20+count);const auto &pack=j.at("extras").at("domeSculptAuthoring");if(report.meshes!=19||pack.at("encoding").get<std::string>()!="scene-cbor-deflate"||pack.contains("images")||j.at("extras").contains("domeSculptEmission"))return 5;auto restored=extract_native_authoring(data);if(!restored||restored->encode()!=original||scene.encode()!=original)return 6;auto again=owner;again.scene=std::make_shared<const Scene>(restored->snapshot());export_glb_authoring(again,out/"second-cycle.glb");if(bytes(out/"second-cycle.glb")!=data)return 7;NativeAuthoringReadLimits limits;limits.max_decoded_native_bytes=128*1024*1024;bool refused=false;try{extract_native_authoring(data,limits);}catch(const std::length_error&){refused=true;}if(!refused)return 8;std::cout<<"PASS Real CC0 male19part sparse-colour authoring compressed envelope, exact native/source/rig/morph restore, no fakeHDR fields, secondcycle byteidentity and explicit expanded cap\n";std::cout<<"bytes="<<data.size()<<" decoded="<<pack.at("native").at("decodedBytes")<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
